```python
from datetime import datetime

def filter_active_users(user_data):
    active_users = []
    for user in user_data:
        try:
            last_active_date = datetime.strptime(user['last_active'], '%Y-%m-%d')
            if datetime.now() - last_active_date < timedelta(days=365):
                active_users.append(user)
        except (ValueError, KeyError):
            # Skip users with invalid or missing dates
            continue
    return active_users
```

